import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "relative inline-flex shrink-0 select-none items-center justify-center gap-2 overflow-hidden whitespace-nowrap rounded-full font-semibold tracking-[-0.01em] outline-none focus-visible:outline-hidden transition-[filter,scale] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] before:pointer-events-none before:absolute before:inset-x-[4px] before:top-[1px] before:h-[46%] before:rounded-[9999px_9999px_8px_8px] before:bg-[image:var(--aqua-gel-shine,linear-gradient(180deg,rgba(255,255,255,0.92)_0%,rgba(255,255,255,0.5)_55%,rgba(255,255,255,0.24)_100%))] before:[mask-image:linear-gradient(90deg,transparent_0%,black_7px,black_calc(100%_-_7px),transparent_100%)] before:content-[''] hover:brightness-105 focus-visible:ring-[3px] focus-visible:ring-[var(--aqua-ring,#2f7de0)] active:scale-[0.97] active:brightness-95 disabled:pointer-events-none disabled:opacity-50 data-disabled:pointer-events-none data-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default:
