        secondary:
          "border border-[var(--aqua-border-strong,#8b9098)] bg-[image:var(--aqua-surface-silver)] text-[var(--aqua-text,#262a30)] shadow-[inset_0_1px_0_rgba(255,255,255,0.95),inset_0_-2px_3px_rgba(255,255,255,0.85),0_1px_2px_rgba(20,30,50,0.14)] dark:shadow-[inset_0_1px_0_rgba(255,255,255,0.22),inset_0_-1px_2px_rgba(255,255,255,0.1),0_1px_2px_rgba(0,0,0,0.45)] before:opacity-75 dark:before:opacity-45 [text-shadow:0_1px_0_rgba(255,255,255,0.9)] dark:[text-shadow:0_-1px_0_rgba(0,0,0,0.5)]",
        destructive:
          "[--aqua-accent:#e03a2f] border border-[var(--aqua-gel-border,#925355)] border-b-[var(--aqua-gel-border-bottom,#8b6769)] bg-[linear-gradient(180deg,var(--aqua-gel-top,#fed0c9)_0%,var(--aqua-gel-upper,#faaca0)_46%,var(--aqua-gel-body,#ec6a5b)_50%,var(--aqua-gel-lower,#f69688)_68%,var(--aqua-gel-top,#fed0c9)_88%,var(--aqua-gel-glow,#ffdfd9)_100%)] text-black dark:text-white dark:[text-shadow:0_-1px_1px_rgba(0,0,0,0.45)] shadow-[inset_0_1px_0_rgba(255,255,255,0.72),inset_0_-2px_4px_var(--aqua-gel-inset-bottom,rgba(255,255,255,0.78)),inset_3px_0_5px_-1px_var(--aqua-gel-rim,rgba(224,58,47,0.58)),inset_-3px_0_5px_-1px_var(--aqua-gel-rim,rgba(224,58,47,0.58)),0_1px_2px_rgba(110,20,20,0.22)] dark:shadow-[inset_0_1px_0_rgba(255,255,255,0.42),inset_0_-2px_5px_var(--aqua-gel-inset-bottom,rgba(224,58,47,0.35)),inset_3px_0_5px_-1px_rgba(0,0,0,0.35),inset_-3px_0_5px_-1px_rgba(0,0,0,0.35),0_1px_3px_rgba(0,0,0,0.5)] [text-shadow:0_1px_0_rgba(255,255,255,0.5)]",
        outline:
          "border border-[var(--aqua-border-strong,#8b909a)] bg-[image:var(--aqua-surface-white)] text-[var(--aqua-text,#3a3f47)] shadow-[inset_0_1px_1px_rgba(255,255,255,0.9),0_1px_2px_rgba(20,60,130,0.16)] before:opacity-40 [text-shadow:0_1px_0_rgba(255,255,255,0.8)] dark:[text-shadow:0_-1px_0_rgba(0,0,0,0.4)]",
        ghost:
          "border border-transparent bg-transparent text-[var(--aqua-text,#3a3f47)] shadow-none before:opacity-0 [text-shadow:0_1px_0_rgba(255,255,255,0.8)] dark:[text-shadow:none] hover:border-[var(--aqua-border-light,#c3c7cf)] hover:bg-[image:var(--aqua-surface-metal)] hover:before:opacity-40",
      },
      size: {
        xs: "px-3.5 py-1 text-xs",
        sm: "px-5 py-[7px] text-sm",
        default: "px-7 py-2.5 text-base",
        lg: "px-8 py-[13px] text-xl",
        "icon-sm": "size-7 p-0 text-sm [&_svg:not([class*='size-'])]:size-3.5",
        icon: "size-9 p-0 [&_svg:not([class*='size-'])]:size-4",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

function Button({
  className,
  variant,
  size,
  pulse = false,
  render,
  ...props
}: useRender.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    /** Throb like the era's default button: one per dialog, the one Return presses. */
    pulse?: boolean;
  }) {
  const defaultProps = {
    "data-slot": "button",
    className: cn(
      buttonVariants({ variant, size }),
      pulse &&
        "animate-[aqua-pulse_1.8s_ease-in-out_infinite] active:animate-none motion-reduce:animate-none",
      className,
    ),
  };

  return useRender({
    defaultTagName: "button",
    render,
    props: mergeProps<"button">(defaultProps, props),
  });
}

export { Button, buttonVariants };
